begin;
select set_config('cb.owner',gen_random_uuid()::text,true),set_config('cb.other',gen_random_uuid()::text,true),set_config('cb.product',gen_random_uuid()::text,true),set_config('cb.basis',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('cb.owner')::uuid,'basis-a@example.invalid'),(current_setting('cb.other')::uuid,'basis-b@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cb.owner'),'role','authenticated')::text,true);set local role authenticated;
insert into public.products(id,name,sale_price) values(current_setting('cb.product')::uuid,'Unknown opening stock',1000);
do $$declare p uuid:=current_setting('cb.product')::uuid;b uuid:=current_setting('cb.basis')::uuid;c uuid:=gen_random_uuid();b2 uuid:=gen_random_uuid();v bigint;x jsonb;old_sale jsonb;new_sale jsonb;n bigint;begin
 perform public.post_stock_adjustment(gen_random_uuid(),p,0,0,3000,'opening count');
 old_sale:=public.post_cash_sale(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',p,'quantity_units',1000,'expected_price',1000)),0,1000,'','');
 select max(movement_no) into v from public.stock_movements where product_id=p;
 select count(*) into n from public.inventory_cost_movements;
 x:=public.get_inventory_cost_basis(p);if x->'product'->'value_iqd'<>'null'::jsonb or x->'product'->>'quantity_units'<>'2000' then raise exception 'unknown snapshot';end if;
 begin perform public.confirm_inventory_cost_basis(gen_random_uuid(),p,3000,v,1000,'stale');raise exception 'stale accepted';exception when raise_exception then if sqlerrm<>'basis_stock_changed' then raise;end if;end;
 begin perform public.confirm_inventory_cost_basis(gen_random_uuid(),p,2000,v-1,1000,'stale version');raise exception 'version accepted';exception when raise_exception then if sqlerrm<>'basis_stock_changed' then raise;end if;end;
 x:=public.confirm_inventory_cost_basis(b,p,2000,v,1200,'verified total invoice cost');if x->>'total_value'<>'1200' then raise exception 'ack total';end if;
 perform public.confirm_inventory_cost_basis(b,p,2000,v,1200,'verified total invoice cost');
 if (select count(*) from public.inventory_cost_bases)<>1 or (select count(*) from public.inventory_cost_movements)<>n or (select quantity_units from public.product_stock where product_id=p)<>2000 or (select count(*) from public.cash_movements)<>1 then raise exception 'basis changed ledger or duplicate';end if;
 begin perform public.confirm_inventory_cost_basis(b,p,2000,v,1201,'verified total invoice cost');raise exception 'conflict accepted';exception when raise_exception then if sqlerrm<>'basis_request_conflict' then raise;end if;end;
 begin perform public.confirm_inventory_cost_basis(gen_random_uuid(),p,2000,v,1200,'replace');raise exception 'known accepted';exception when raise_exception then if sqlerrm<>'basis_cost_already_known' then raise;end if;end;
 perform public.cancel_inventory_cost_basis(c,p,b,'wrong evidence');perform public.cancel_inventory_cost_basis(c,p,b,'wrong evidence');
 if (select value_iqd from public.inventory_cost_state where product_id=p) is not null or (select count(*) from public.inventory_cost_basis_cancellations)<>1 then raise exception 'cancel retry';end if;
 begin perform public.cancel_inventory_cost_basis(gen_random_uuid(),p,b,'again');raise exception 'double cancel';exception when raise_exception then if sqlerrm<>'basis_already_cancelled' then raise;end if;end;
 perform public.confirm_inventory_cost_basis(b2,p,2000,v,1200,'correct evidence');
 new_sale:=public.post_cash_sale(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',p,'quantity_units',1000,'expected_price',1000)),0,1000,'','');
 if (select -c.value_delta from public.inventory_cost_movements c join public.stock_movements m on m.id=c.id where m.sale_id=(new_sale->>'id')::uuid)<>600 then raise exception 'future COGS incorrect';end if;
 if (select c.value_delta from public.inventory_cost_movements c join public.stock_movements m on m.id=c.id where m.sale_id=(old_sale->>'id')::uuid) is not null then raise exception 'historical cost rewritten';end if;
 perform public.post_sale_reversal(gen_random_uuid(),(new_sale->>'id')::uuid,'restore quantity');
 begin perform public.cancel_inventory_cost_basis(gen_random_uuid(),p,b2,'after movement');raise exception 'used basis cancelled';exception when raise_exception then if sqlerrm<>'basis_used_by_movement' then raise;end if;end;
 select max(movement_no) into v from public.stock_movements where product_id=p;
 perform public.post_stock_adjustment(gen_random_uuid(),p,2000,v,3000,'new uncosted stock');select max(movement_no) into v from public.stock_movements where product_id=p;
 perform public.confirm_inventory_cost_basis(gen_random_uuid(),p,3000,v,0,'verified donated stock total');
 x:=public.get_inventory_cost_basis(p);if x->'product'->>'value_iqd'<>'0' or jsonb_array_length(x->'history')<>3 then raise exception 'zero or audit missing';end if;
 x:=public.export_owner_data();if x->>'version'<>'7' or (select count(*) from jsonb_object_keys(x->'tables'))<>29 or x->'counts'->>'inventory_cost_bases'<>'3' then raise exception 'export basis missing';end if;
 begin delete from public.inventory_cost_bases;raise exception 'direct delete';exception when insufficient_privilege then null;end;
 begin update public.inventory_cost_basis_cancellations set reason='rewrite';raise exception 'direct update';exception when insufficient_privilege then null;end;
 begin insert into public.inventory_cost_bases(id) values(gen_random_uuid());raise exception 'direct insert';exception when insufficient_privilege then null;end;
end $$;
reset role;set constraints all immediate;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('cb.other'),'role','authenticated')::text,true);set local role authenticated;
do $$begin
 if exists(select 1 from public.inventory_cost_bases) or exists(select 1 from public.inventory_cost_basis_cancellations) then raise exception 'history RLS leak';end if;
 begin perform public.get_inventory_cost_basis(current_setting('cb.product')::uuid);raise exception 'foreign read';exception when raise_exception then if sqlerrm<>'basis_product_unavailable' then raise;end if;end;
 begin perform public.confirm_inventory_cost_basis(current_setting('cb.basis')::uuid,current_setting('cb.product')::uuid,2000,0,1,'foreign');raise exception 'foreign retry';exception when raise_exception then if sqlerrm<>'basis_request_conflict' then raise;end if;end;
end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_inventory_cost_basis(current_setting('cb.product')::uuid);raise exception 'missing uid';exception when raise_exception then if sqlerrm<>'basis_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_inventory_cost_basis(current_setting('cb.product')::uuid);raise exception 'anonymous read';exception when insufficient_privilege then null;end;end $$;
reset role;
select 'PASS: unknown basis, exact total, stale stock, retries, conflict, cancel, movement lock, future-only COGS, zero value, audit/export and owner isolation' as verification;
rollback;
